const ANGULO_CRITICO = 45; // Grados críticos (cámbialo si quieres)
const MUESTRAS = 10;       // Memoria de los últimos 10 valores
const MAYORIA = 6;         // Cuántos deben fallar para pitar

let history = context.get('history') || [];
let isWarningActive = context.get('isWarningActive') || false;

// Leer el ángulo que entra
let angulo = parseFloat(msg.payload);
if (isNaN(angulo)) return null;

// Actualizar el historial de los últimos 10 valores
history.push(angulo);
if (history.length > MUESTRAS) {
    history.shift();
}
context.set('history', history);

// Contar cuántos valores superan el ángulo crítico (en positivo o negativo)
let countCritical = 0;
for (let i = 0; i < history.length; i++) {
    if (Math.abs(history[i]) >= ANGULO_CRITICO) {
        countCritical++;
    }
}

// Lógica de disparo y filtro anti-spam
if (countCritical >= MAYORIA && !isWarningActive) {
    context.set('isWarningActive', true);
    return { payload: "Bank angle, bank angle" };
} else if (countCritical < MAYORIA && isWarningActive) {
    // Si el avión se endereza, rearmamos la alarma
    context.set('isWarningActive', false);
}

return null;
